/// Each mark's layers, bottom first: glyph, light-theme colour, dark-theme colour.
/// `currentColor` takes the foreground, as web's `text-foreground` does.
pub fn layers(editor: &str) -> Option<&'static [(&'static Icon, &'static str, &'static str)]> {
    Some(match editor {
        "cursor" => &[(&CURSOR_0, "#26251E", "#EDECEC")],
        "trae" => &[(&TRAE_0, "currentColor", "currentColor")],
        "kiro" => &[(&KIRO_0, "#9046FF", "#9046FF"), (&KIRO_1, "#FFFFFF", "#FFFFFF"), (&KIRO_2, "#000000", "#000000")],
        "vscode" => &[(&VSCODE_0, "#0065A9", "#0065A9"), (&VSCODE_1, "#007ACC", "#007ACC"), (&VSCODE_2, "#1F9CF0", "#1F9CF0")],
        "vscode-insiders" => &[(&VSCODE_INSIDERS_0, "#009A7C", "#009A7C"), (&VSCODE_INSIDERS_1, "#00B294", "#00B294"), (&VSCODE_INSIDERS_2, "#24BFA5", "#24BFA5")],
        "vscodium" => &[(&VSCODIUM_0, "#3E80CF", "#3E80CF")],
        "zed" => &[(&ZED_0, "currentColor", "currentColor")],
        "idea" => &[(&IDEA_0, "#FF8100", "#FF8100"), (&IDEA_1, "#FE384C", "#FE384C"), (&IDEA_2, "#685BBA", "#685BBA"), (&IDEA_3, "#000000", "#000000"), (&IDEA_4, "#FFFFFF", "#FFFFFF")],
        "aqua" => &[(&AQUA_0, "#376AFE", "#376AFE"), (&AQUA_1, "#5F6CEB", "#5F6CEB"), (&AQUA_2, "#00D886", "#00D886"), (&AQUA_3, "#000000", "#000000"), (&AQUA_4, "#FFFFFF", "#FFFFFF")],
        "clion" => &[(&CLION_0, "#00BAB1", "#00BAB1"), (&CLION_1, "#2B88D7", "#2B88D7"), (&CLION_2, "#FF2D90", "#FF2D90"), (&CLION_3, "#000000", "#000000"), (&CLION_4, "#FFFFFF", "#FFFFFF")],
        "datagrip" => &[(&DATAGRIP_0, "#30A2B5", "#30A2B5"), (&DATAGRIP_1, "#8A53FD", "#8A53FD"), (&DATAGRIP_2, "#FF43F2", "#FF43F2"), (&DATAGRIP_3, "#000000", "#000000"), (&DATAGRIP_4, "#FFFFFF", "#FFFFFF")],
        "dataspell" => &[(&DATASPELL_0, "#00AAC0", "#00AAC0"), (&DATASPELL_1, "#3495CC", "#3495CC"), (&DATASPELL_2, "#F0EB18", "#F0EB18"), (&DATASPELL_3, "#000000", "#000000"), (&DATASPELL_4, "#FFFFFF", "#FFFFFF")],
        "goland" => &[(&GOLAND_0, "#00D886", "#00D886"), (&GOLAND_1, "#0080FA", "#0080FA"), (&GOLAND_2, "#7061FD", "#7061FD"), (&GOLAND_3, "#000000", "#000000"), (&GOLAND_4, "#FFFFFF", "#FFFFFF")],
        "phpstorm" => &[(&PHPSTORM_0, "#D249FC", "#D249FC"), (&PHPSTORM_1, "#F9319E", "#F9319E"), (&PHPSTORM_2, "#B842C8", "#B842C8"), (&PHPSTORM_3, "#000000", "#000000"), (&PHPSTORM_4, "#FFFFFF", "#FFFFFF")],
        "pycharm" => &[(&PYCHARM_0, "#00D886", "#00D886"), (&PYCHARM_1, "#C4E82C", "#C4E82C"), (&PYCHARM_2, "#78D886", "#78D886"), (&PYCHARM_3, "#000000", "#000000"), (&PYCHARM_4, "#FFFFFF", "#FFFFFF")],
        "rider" => &[(&RIDER_0, "#007DFE", "#007DFE"), (&RIDER_1, "#D9AE25", "#D9AE25"), (&RIDER_2, "#FF5A38", "#FF5A38"), (&RIDER_3, "#000000", "#000000"), (&RIDER_4, "#FFFFFF", "#FFFFFF")],
        "rubymine" => &[(&RUBYMINE_0, "#BF3AA4", "#BF3AA4"), (&RUBYMINE_1, "#FF3844", "#FF3844"), (&RUBYMINE_2, "#FF8100", "#FF8100"), (&RUBYMINE_3, "#000000", "#000000"), (&RUBYMINE_4, "#FFFFFF", "#FFFFFF")],
        "rustrover" => &[(&RUSTROVER_0, "#00D886", "#00D886"), (&RUSTROVER_1, "#FFAB00", "#FFAB00"), (&RUSTROVER_2, "#FF5825", "#FF5825"), (&RUSTROVER_3, "#000000", "#000000"), (&RUSTROVER_4, "#FFFFFF", "#FFFFFF")],
        "webstorm" => &[(&WEBSTORM_0, "#F0EB18", "#F0EB18"), (&WEBSTORM_1, "#3ACDBE", "#3ACDBE"), (&WEBSTORM_2, "#00A2F9", "#00A2F9"), (&WEBSTORM_3, "#000000", "#000000"), (&WEBSTORM_4, "#FFFFFF", "#FFFFFF")],
        "finder" => &[(&FINDER_0, "#36A9F5", "#36A9F5"), (&FINDER_1, "#D9F1FF", "#D9F1FF"), (&FINDER_2, "#163A59", "#163A59")],
        "file-explorer" => &[(&FILE_EXPLORER_0, "#D99A16", "#D99A16"), (&FILE_EXPLORER_1, "#FFCE45", "#FFCE45"), (&FILE_EXPLORER_2, "#58B8E8", "#58B8E8"), (&FILE_EXPLORER_3, "#1879B9", "#1879B9")],
        _ => return None,
    })
}
